function _qv2ResolveMedia(src) {
  if (!src) return '';
  if (/^https?:\/\//i.test(src)) return src;
  if (src.charAt(0) === '/') {
    const base = _qv2Base();
    return (base && src.indexOf('/api/') === 0) ? base + src : src;
  }
  if (src.indexOf('./') === 0) return src;
  return './' + src; // relative asset served by the frontend (public/exam-media/…)
}

